// Generated by scripts/fleet/sync_agents.py: edit the generator, then run `make agents`.
// omp (oh-my-pi) loads every .ts in .omp/extensions. The same Rekkit guards as the opencode plugin and the
// Claude Code and agy hooks (scripts/fleet/hook.sh): no push, sign, release, submodule change, force or
// recursive delete; nothing under horizon/; no code under mods/<id>/content/; no whole decompiled class; no
// folder sweeps or toolchain reads by a role subagent. And the tracker context (its resume page, while a mod is
// in progress its resume page) in the main session's system prompt, again after compaction.
// There is no stop gate in omp: `make agent-gate MOD=<id>` before you stop (AGENTS.md), and a mod is
// finished only when `make contract-check` and the live harness's render, GUI and scenario checks pass.
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const HOOK = fileURLToPath(new URL("../../scripts/fleet/hook.sh", import.meta.url));
// omp's tools -> the guard each gets. `task` is omp's subagent tool; `grep`/`find`/`ls` are reads.
const CHECKS = { bash: "shell", edit: "paths", write: "paths", patch: "paths", notebook: "paths",
                 read: "read", grep: "read", find: "read", glob: "read", ls: "read", list: "read" };
const SUBAGENT_TOOLS = new Set(["task", "subagent"]);

const guard = (check, payload) =>
  spawnSync("bash", [HOOK, check, "claude"], { input: JSON.stringify(payload ?? {}), encoding: "utf8" });
const prime = () => {
  const r = guard("prime");
  return r.status === 0 ? (r.stdout || "").trim() : "";
};
let primed = null; // one text per session, so the system prompt stays the same (and cached) turn to turn

export default function rekkitGuard(pi) {
  // A blocked call returns { block: true, reason }: the reason goes back to the model.
  pi.on("tool_call", async (event, ctx) => {
    const tool = String(event.toolName ?? "").toLowerCase();
    // Subagents run only under Claude Code, agy and grok; a local model (Ollama, LM Studio, llama.cpp), which
    // omp usually runs, never does. A cloud-model session may set REKKIT_ALLOW_SUBAGENTS=1.
    if (SUBAGENT_TOOLS.has(tool) && process.env.REKKIT_ALLOW_SUBAGENTS !== "1")
      return { block: true, reason: "Subagents are off on omp: do the role yourself, one ticket at a time (AGENTS.md)." };
    const check = CHECKS[tool];
    if (!check) return;
    const sessionId = ctx?.sessionManager?.getSessionId?.() ?? "";
    const r = guard(check, { session_id: sessionId, tool_name: tool, tool_input: event.input ?? {} });
    if (r.status === 2) return { block: true, reason: (r.stderr || "Blocked by the Rekkit fleet guard").trim() };
  });
  pi.on("before_agent_start", async (event) => {
    if (primed === null) primed = prime();
    if (!primed) return;
    const system = Array.isArray(event.systemPrompt) ? event.systemPrompt : [String(event.systemPrompt ?? "")];
    if (system.includes(primed)) return;
    return { systemPrompt: [...system, primed] };
  });
  // After compaction the next request re-reads the tracker context.
  pi.on("session_before_compact", async () => {
    primed = null;
  });
  pi.on("session_start", async () => {
    primed = null;
  });
}
